head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[accordion > M > openPanel]<br/>파라미터로 지정한 ID 에 해당하는 패널을 엽니다.",
    "validation" : [
        "id(필수) 파라미터로 지정한 ID 에 해당하는 패널을 엽니다.",
        "collapsible, independentPanel 속성값에 따라 다른 패널의 자동 닫기 동작이 달라집니다.",
        "비활성화(disabled) 상태의 패널은 열리지 않습니다.",
        "collapsible=true, independentPanel=false 이면 openPanel() 메소드 실행 시 다른 열린 패널을 자동으로 닫습니다.",
        "collapsible=true, independentPanel=true 이거나 collapsible=false 이면 openPanel() 메소드 실행 시 다른 열린 패널을 닫지 않습니다.",
        "다른 열린 패널이 자동으로 닫히는 경우 해당 패널에 대해 onpanelunload 이벤트가 간접적으로 발생합니다.",
        "패널 열기가 완료되면 onpanelload 이벤트가 비동기로 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (con_collapsible, con_independentPanel)
    let properties = {
        collapsible : con_collapsible.getText(),
        independentPanel : con_independentPanel.getText(),
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onpanelload", "onpanelunload"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="* openPanel(id) 호출 시 par_id 의 패널이 열리는지 확인 (panels3 는 disabledPanels=true → 안 열림)"', '', 'label1');
    $c.gcm.createLabel('label="* collapsible=true, independentPanel=false → openPanel 호출 시 다른 열린 패널이 자동 닫힘 (onpanelunload 간접 발생)"', '', 'label2');
    $c.gcm.createLabel('label="* collapsible=true + independentPanel=true 또는 collapsible=false → openPanel 호출 시 다른 열린 패널은 닫히지 않음"', '', 'label3');
    $c.gcm.createLabel('label="* 패널 열기 완료 → onpanelload 이벤트 비동기 발생 (핸들러 출력 확인)"', '', 'label4');

    strTarget += '<w2:accordion ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" style="width:240px; height:320px;">';
    strTarget += '<w2:panels style="" id="panels1" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle1" label="panelTitle1"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent1">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel1"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels2" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle2" label="panelTitle2"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent2">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel2"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels3" class="" disabledPanels="true">';
    strTarget += '<w2:panelTitle style="" id="panelTitle3" label="panelTitle3 (disabled)"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent3">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel3"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '</w2:accordion>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "accordion",
        strTarget,
        grp_comp
    );
}



// onpanelload 핸들러 — 가이드 @param : <String> panelID, <String> userID
scwin.target1_onpanelload = function (panelID, userID) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onpanelload 이벤트 발생]");
};



// onpanelunload 핸들러 — 다른 패널 자동 닫힘 시 간접 발생 확인
scwin.target1_onpanelunload = function (panelID, userID) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onpanelunload 이벤트 발생]");
};



// openPanel(par_id) 호출 — id 파라미터로 지정한 패널 열기 시도
scwin.btn_openPanel_onclick = function (e) {
    let panelId = par_id.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("===== openPanel('" + panelId + "') 호출 =====");
    target1.openPanel(panelId);
};



// 모두 열기 — openPanel 반복 호출 (collapsible/independentPanel 조합별 자동 닫기 거동 확인)
scwin.btn_openAll_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== 모두 열기 (openPanel 반복 호출) =====");
    target1.openPanel("panels1");
    target1.openPanel("panels2");
    target1.openPanel("panels3");
};



// 모두 닫기 — closePanel 반복 호출 (초기 상태 리셋용)
scwin.btn_closeAll_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== 모두 닫기 (closePanel 반복 호출) =====");
    target1.closePanel("panels1");
    target1.closePanel("panels2");
    target1.closePanel("panels3");
};



// 열린 패널 확인 — getOpenPanelListInfo 결과 출력
scwin.btn_getOpenPanel_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== getOpenPanelListInfo() 결과 =====");
    let openList = target1.getOpenPanelListInfo();
    wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 수 : " + (openList ? openList.length : 0));
    if (openList && openList.length > 0) {
        for (let i = 0; i < openList.length; i++) {
            wf_body_bottom.getObj("scwin").setReturnValue("열린 패널[" + i + "] id : " + openList[i].id);
        }
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 없음");
    }
};
